import { Outlet, useRouterState } from "@tanstack/react-router";
import { Search } from "lucide-react";
import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { Button } from "@/ui/primitives/button";
import { Kbd, KbdGroup } from "@/ui/primitives/kbd";
import { Separator } from "@/ui/primitives/separator";
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/ui/primitives/sidebar";
import { usePersisted } from "@/ui/use-persisted";
import { cn } from "@/ui/utils";
import { AppSidebar, type Brand } from "./app-sidebar";
import { CommandPalette } from "./command-palette";
import {
  CommandRegistryContext,
  type Command,
  type CommandRegistry,
} from "./command-palette-state";
import type { NavConfig } from "./nav";

export type { Brand };

/**
 * The frame of every page, on shadcn's Sidebar: the sidebar (collapses to icons on
 * desktop with Ctrl+B or the rail, a sheet on a phone), the header with the command
 * palette (Ctrl+K or ⌘K), and the page in the sidebar inset.
 */
export function AppShell({
  nav,
  brand,
  headerEnd,
  sidebarFooter,
  fullHeight,
  storageKey = "app.navCollapsed",
  children,
}: {
  nav: NavConfig;
  brand: Brand;
  /** Chips and buttons at the right of the header: status, the user menu. */
  headerEnd?: ReactNode;
  sidebarFooter?: (collapsed: boolean) => ReactNode;
  /** Pages that scroll their own panes get a fixed-height `<main>` instead of a scrolling one. */
  fullHeight?: (pathname: string) => boolean;
  /** The localStorage key that remembers whether the sidebar is collapsed. */
  storageKey?: string;
  /** The page. Defaults to the router's `<Outlet />`. */
  children?: ReactNode;
}) {
  const pathname = useRouterState({ select: (state) => state.location.pathname });
  const [palette, setPalette] = useState(false);
  const [collapsed, setCollapsed] = usePersisted(storageKey, false);
  const [owners, setOwners] = useState<Record<string, Command[]>>({});

  const register = useCallback(
    (owner: string, commands: Command[]) => setOwners((all) => ({ ...all, [owner]: commands })),
    [],
  );
  const unregister = useCallback(
    (owner: string) =>
      setOwners((all) => {
        const next = { ...all };
        delete next[owner];
        return next;
      }),
    [],
  );
  const registry = useMemo<CommandRegistry>(
    () => ({ register, unregister }),
    [register, unregister],
  );
  const commands = useMemo(() => Object.values(owners).flat(), [owners]);

  useEffect(() => {
    function onKey(event: KeyboardEvent) {
      if (event.key.toLowerCase() === "k" && (event.ctrlKey || event.metaKey)) {
        event.preventDefault();
        setPalette((open) => !open);
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <CommandRegistryContext.Provider value={registry}>
      <SidebarProvider
        open={!collapsed}
        onOpenChange={(open) => setCollapsed(!open)}
        className="h-dvh min-h-0 overflow-hidden bg-background text-foreground"
        style={{ "--sidebar-width": "13rem" } as CSSProperties}
      >
        <AppSidebar nav={nav} brand={brand} footer={sidebarFooter} pathname={pathname} />
        <SidebarInset className="min-w-0 overflow-hidden">
          <header className="flex h-14 shrink-0 items-center gap-2 border-b border-border px-3">
            <SidebarTrigger />
            <Separator orientation="vertical" className="mr-1 data-[orientation=vertical]:h-4" />
            <Button
              type="button"
              variant="ghost"
              onClick={() => setPalette(true)}
              className="mr-auto h-10 min-w-0 flex-1 justify-start gap-2 bg-inset px-3 font-normal shadow-[var(--shadow-border)] hover:bg-inset hover:shadow-[var(--shadow-border-hover)] lg:max-w-md"
            >
              <Search />
              <span className="min-w-0 flex-1 truncate text-left">Search…</span>
              <KbdGroup className="hidden sm:inline-flex">
                <Kbd>Ctrl</Kbd>
                <Kbd>K</Kbd>
              </KbdGroup>
            </Button>
            {headerEnd}
          </header>
          <div
            className={cn(
              "min-h-0 min-w-0 flex-1",
              fullHeight?.(pathname) ? "flex flex-col overflow-hidden" : "overflow-y-auto",
            )}
          >
            {children ?? <Outlet />}
          </div>
        </SidebarInset>
        <CommandPalette open={palette} onOpenChange={setPalette} nav={nav} commands={commands} />
      </SidebarProvider>
    </CommandRegistryContext.Provider>
  );
}

import { Link } from "@tanstack/react-router";
import type { LucideIcon } from "lucide-react";
import type { ComponentProps, ReactNode } from "react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
  SidebarSeparator,
} from "@/ui/primitives/sidebar";
import { useSidebar } from "@/ui/primitives/sidebar-context";
import type { NavConfig } from "./nav";
import { NavMain } from "./nav-main";

export type Brand = {
  name: string;
  /** A second line under the name, such as the product area. */
  tagline?: string;
  icon: LucideIcon;
};

/**
 * The app's sidebar, after shadcn's sidebar-07 block: it collapses to icons on desktop
 * and is a sheet on a phone. The brand sits in the header, the primary and secondary
 * nav below it, and the caller's footer at the bottom.
 */
export function AppSidebar({
  nav,
  brand,
  footer,
  pathname,
  ...props
}: ComponentProps<typeof Sidebar> & {
  nav: NavConfig;
  brand: Brand;
  footer?: (collapsed: boolean) => ReactNode;
  pathname: string;
}) {
  const { state, isMobile, setOpenMobile } = useSidebar();
  const collapsed = state === "collapsed" && !isMobile;
  const Icon = brand.icon;
  return (
    <Sidebar collapsible="icon" {...props}>
      <SidebarHeader className="h-14 justify-center py-0">
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg" asChild tooltip={brand.name} className="h-10">
              <Link
                to="/"
                onClick={() => {
                  if (isMobile) setOpenMobile(false);
                }}
              >
                <span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-secondary text-muted-foreground shadow-[var(--shadow-border)]">
                  <Icon className="size-4" />
                </span>
                <span className="grid flex-1 text-left leading-tight">
                  <span className="truncate text-sm font-semibold tracking-tight">
                    {brand.name}
                  </span>
                  {brand.tagline ? (
                    <span className="truncate text-[11px] text-muted-foreground">
                      {brand.tagline}
                    </span>
                  ) : null}
                </span>
              </Link>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarHeader>
      <SidebarContent className="gap-0">
        <NavMain items={nav.primary} pathname={pathname} />
        {nav.secondary?.length ? (
          <>
            <SidebarSeparator />
            <NavMain items={nav.secondary} pathname={pathname} />
          </>
        ) : null}
      </SidebarContent>
      {footer ? (
        <SidebarFooter className={collapsed ? "items-center px-2 py-3" : "px-3 py-3"}>
          {footer(collapsed)}
        </SidebarFooter>
      ) : null}
      <SidebarRail />
    </Sidebar>
  );
}

import { Link } from "@tanstack/react-router";
import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/ui/primitives/sidebar";
import { useSidebar } from "@/ui/primitives/sidebar-context";
import { isNavActive, type NavItem } from "./nav";

/**
 * One group of nav links, as in shadcn's sidebar-07 block: a SidebarMenuButton per
 * item, with its label as the tooltip when the sidebar is collapsed to icons.
 */
export function NavMain({
  items,
  pathname,
  label,
}: {
  items: readonly NavItem[];
  pathname: string;
  /** A heading over the group; it hides when the sidebar is collapsed. */
  label?: string;
}) {
  const { isMobile, setOpenMobile } = useSidebar();
  return (
    <SidebarGroup>
      {label ? <SidebarGroupLabel>{label}</SidebarGroupLabel> : null}
      <SidebarGroupContent>
        <SidebarMenu className="gap-0.5">
          {items.map((item) => {
            const active = isNavActive(pathname, item.to);
            const Icon = item.icon;
            return (
              <SidebarMenuItem key={item.to}>
                <SidebarMenuButton
                  asChild
                  isActive={active}
                  tooltip={item.label}
                  className="h-9 text-muted-foreground data-[active=true]:font-medium data-[active=true]:text-foreground"
                >
                  <Link
                    to={item.to}
                    aria-current={active ? "page" : undefined}
                    onClick={() => {
                      if (isMobile) setOpenMobile(false);
                    }}
                  >
                    <Icon />
                    <span>{item.label}</span>
                  </Link>
                </SidebarMenuButton>
              </SidebarMenuItem>
            );
          })}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}
